<template>
  <div class="demo-page">
    <header>
      <p class="demo-page__eyebrow">远程组件</p>
      <h1 class="demo-page__title">comps-vue3 · FilmRoll</h1>
      <p class="demo-page__lead">
        来自 video-code 的「旅行胶卷」：一条横向胶片，每格带上下片边、齿孔编号和时间戳。拖动时整条会跟着
        速度被「拉扯」—— 离中心越远越暗越糊越小，飞快拖动时叠出重影和倾斜；松手先惯性滑动再吸附到最近一格。
        原 demo 是一整页（页头 / 标题 / 页脚 / 时间轴都是页面级编排），组件里只保留胶卷本体、详情和时间轴。
      </p>
    </header>

    <section class="film-demo">
      <div class="film-demo__head">
        <h2 class="demo-page__section-title">拖动 · 惯性 · 吸附</h2>
        <code class="film-demo__tag">{{ index + 1 }} / {{ photos.length }}</code>
      </div>
      <p class="demo-card__text">
        按住左右拖动，松手看它自己滑一段再停到最近一格；也可以滚轮翻、方向键翻、点底部时间轴跳转。
        点击当前这张打开全屏预览（Esc 关闭，← → 在预览里也能翻）。
      </p>

      <div class="film-demo__stage">
        <FilmRoll v-model:index="index" :photos="photos" @change="onChange" @open="onOpen" />
      </div>

      <p class="film-demo__hint">
        当前：<code>{{ photos[index]?.place }}</code> · 最近一次：<code>{{ lastAction }}</code>
      </p>

      <div class="film-demo__row">
        <div class="film-demo__cell">
          <FilmRoll
            :photos="photos.slice(0, 4)"
            :frame="200"
            :photo-height="140"
            :gap="14"
            :details="false"
            :timeline="false"
            :controls="false"
            roll-label="FUJI 业务卷"
          />
          <p>小尺寸 + 关掉详情 / 时间轴（<code>frame</code> / <code>photoHeight</code> / <code>details</code>）</p>
        </div>
        <div class="film-demo__cell">
          <FilmRoll
            :photos="photos.slice(4)"
            :frame="200"
            :photo-height="140"
            :gap="14"
            :details="false"
            :timeline="false"
            :controls="false"
            :viewer="false"
            roll-label="ILFORD 黑白"
            roll-sub-label="只读浏览"
          />
          <p>关掉全屏预览（<code>:viewer="false"</code>），纯展示用</p>
        </div>
      </div>
    </section>

    <DemoPreview class="film-preview">
      <LevaPlayground
        name="FilmRoll"
        :component="FilmRoll"
        :schema="FilmRollSchema"
        :presets="{ photos, frame: 380, photoHeight: 260, gap: 22 }"
        stage-class="is-dark"
        :stage-style="stageStyle"
      />
    </DemoPreview>

    <p class="demo-note">
      <span>
        面板里 <code>frame</code> / <code>photoHeight</code> / <code>gap</code> 是单格尺寸与间距，
        <code>index</code> 是当前第几张（和 <code>v-model:index</code> 同步），<code>rollLabel</code> /
        <code>rollSubLabel</code> 是胶片上下那两行小字；<code>draggable</code> / <code>wheelable</code> /
        <code>details</code> / <code>controls</code> / <code>timeline</code> / <code>viewer</code>
        是各项交互开关。<code>photos</code> 是数组（面板不生成控件），每项
        <code>{ src, place, date, time, note }</code>。
      </span>
    </p>
  </div>
</template>

<script setup lang="ts">
import { ref } from 'vue'
import FilmRollSchema from '@melt-js/comps-vue3/src/components/FilmRoll.propsSchema.json'
import DemoPreview from '../components/DemoPreview.vue'
import LevaPlayground from '../components/LevaPlayground.vue'
import { remoteComponent } from '../configs/remote'

const FilmRoll = remoteComponent('FilmRoll')

type Photo = { src: string; place: string; date: string; time: string; note: string }

const STOPS: [string, string, string, string][] = [
  ['万里长城', '2026.05.12', '16:42', '沿着山脊走，风把远方一层层展开。'],
  ['故宫', '2026.05.13', '08:16', '红墙映着天光，走过的每一步都有回响。'],
  ['天坛', '2026.05.14', '07:30', '在蓝色琉璃瓦下，留住一个安静的清晨。'],
  ['黄浦江畔', '2026.05.15', '15:05', '江风穿过城市，把新旧时光吹到一起。'],
  ['雨中老街', '2026.05.16', '10:28', '雨落在屋檐上，脚步也跟着慢了下来。'],
  ['桂林山水', '2026.05.17', '14:50', '山峰一座挨着一座，像走进未干的水墨。'],
  ['云山之间', '2026.05.18', '09:12', '云雾从山谷升起，眼前的山有了仙气。'],
  ['古城巷陌', '2026.05.19', '17:36', '在古城的街巷里，把匆忙留给远方。'],
  ['敦煌戈壁', '2026.05.20', '18:04', '沙丘的脊线被落日压成一条金边。'],
  ['青海湖畔', '2026.05.21', '06:20', '湖面比天空还安静，风是唯一的声响。'],
  ['纳木错', '2026.05.22', '12:48', '海拔四千米，连云都走得很慢。'],
  ['珠峰大本营', '2026.05.23', '05:56', '等到日照金山那一刻，冷也值得。'],
]

const PALETTE = [
  ['#1f2937', '#7c3a1d'],
  ['#7f1d1d', '#c2410c'],
  ['#134e4a', '#0e7490'],
  ['#1e3a8a', '#312e81'],
  ['#374151', '#6b7280'],
  ['#14532d', '#166534'],
  ['#3f3f46', '#57534e'],
  ['#4c1d95', '#6d28d9'],
  ['#78350f', '#b45309'],
  ['#0c4a6e', '#0369a1'],
  ['#1e293b', '#0891b2'],
  ['#450a0a', '#9a3412'],
]

/** 生成一张带地名首字的渐变底片，避免依赖外网图 */
function frame(index: number, place: string): string {
  const [from, to] = PALETTE[index % PALETTE.length]
  const svg = `<svg xmlns="http://www.w3.org/2000/svg" width="600" height="420">
    <defs>
      <linearGradient id="g" x1="0" y1="0" x2="1" y2="1">
        <stop offset="0" stop-color="${from}"/><stop offset="1" stop-color="${to}"/>
      </linearGradient>
      <radialGradient id="v" cx="50%" cy="42%" r="72%">
        <stop offset="0" stop-color="#fff" stop-opacity=".16"/>
        <stop offset="1" stop-color="#000" stop-opacity=".38"/>
      </radialGradient>
    </defs>
    <rect width="600" height="420" fill="url(#g)"/>
    <rect width="600" height="420" fill="url(#v)"/>
    <circle cx="452" cy="96" r="46" fill="#fff" opacity=".2"/>
    <path d="M0 330 L150 232 L268 318 L392 208 L520 300 L600 254 L600 420 L0 420 Z"
      fill="#000" opacity=".22"/>
    <text x="300" y="248" font-family="'PingFang SC','Microsoft YaHei',serif"
      font-size="64" font-weight="700" fill="rgba(255,255,255,.9)" text-anchor="middle">${place}</text>
  </svg>`
  return `data:image/svg+xml;utf8,${encodeURIComponent(svg)}`
}

const photos: Photo[] = STOPS.map(([place, date, time, note], index) => ({
  src: frame(index, place),
  place,
  date,
  time,
  note,
}))

const index = ref(0)
const lastAction = ref('（还没翻过）')

const stageStyle = {
  display: 'block',
  height: '520px',
  padding: '0',
  background: '#141512',
}

function onChange(next: number, photo: Photo) {
  lastAction.value = `切到第 ${next + 1} 张 · ${photo.place}`
}

function onOpen(next: number, photo: Photo) {
  lastAction.value = `打开了 ${photo.place} 的全屏预览`
}
</script>

